import json
from fractions import Fraction
from math import gcd, lcm

c = Fraction(20, -24) - (Fraction(2) + Fraction(-3))
original = [Fraction(1), Fraction(0), Fraction(1, 8),
            -c, Fraction(1, 16)]
derivative = [i * original[i] for i in range(1, len(original))]

def divisors(n):
    n = abs(n)
    return [d for d in range(1, n + 1) if n % d == 0]

def evaluate(poly, x):
    result = Fraction(0)
    for coefficient in reversed(poly):
        result = result * x + coefficient
    return result

def divide_by_root(poly, root):
    quotient = [Fraction(0)] * (len(poly) - 1)
    quotient[-1] = poly[-1]
    for i in range(len(quotient) - 2, -1, -1):
        quotient[i] = poly[i + 1] + root * quotient[i + 1]
    assert poly[0] + root * quotient[0] == 0
    return quotient

poly = derivative[:]
roots = []
while len(poly) > 1:
    if poly[0] == 0:
        root = Fraction(0)
    else:
        scale = lcm(*(v.denominator for v in poly))
        integers = [int(v * scale) for v in poly]
        common = 0
        for value in integers:
            common = gcd(common, abs(value))
        integers = [v // common for v in integers]
        candidates = {
            Fraction(sign * p, q)
            for p in divisors(integers[0])
            for q in divisors(integers[-1])
            for sign in (-1, 1)
        }
        root = next(
            (r for r in sorted(candidates) if evaluate(poly, r) == 0),
            None
        )
        if root is None:
            print("UNSUPPORTED")
            raise SystemExit
    roots.append(root)
    poly = divide_by_root(poly, root)

scalar = poly[0]
reconstructed = [scalar]
for root in roots:
    product = [Fraction(0)] * (len(reconstructed) + 1)
    for i, coefficient in enumerate(reconstructed):
        product[i] -= root * coefficient
        product[i + 1] += coefficient
    reconstructed = product
assert reconstructed == derivative

factors = []
for root in sorted(set(roots)):
    multiplicity = roots.count(root)
    if root == 0:
        factor = "s"
    elif root > 0:
        factor = f"(s - {root})"
    else:
        factor = f"(s + {-root})"
    if multiplicity > 1:
        factor += f"^{multiplicity}"
    factors.append(factor)

answer = f"({scalar}) * " + " * ".join(factors)
print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "c": str(c),
        "k_coefficients_ascending": [str(v) for v in derivative],
        "roots_with_multiplicity": [str(r) for r in roots],
        "factor_expansion_verified": reconstructed == derivative
    }
}, separators=(",", ":")))
